import json
from typing import Any

_DEFAULT_SEPARATORS = (",", ":")


def dumps_sorted(obj: Any) -> str:
    return json.dumps(obj, sort_keys=True, separators=_DEFAULT_SEPARATORS)


def loads_strict(text: str) -> Any:
    return json.loads(text)
